CREATE DATABASE EWS;
USE EWS;

CREATE TABLE alert (
    alert_id INTEGER NOT NULL,
    entity_type VARCHAR(20) NOT NULL,
    entity_key INTEGER NOT NULL,
    score_id INTEGER NOT NULL,
    alert_date VARCHAR(20) NOT NULL,
    severity VARCHAR(20) NOT NULL,
    alert_status VARCHAR(30) NOT NULL,
    assigned_to VARCHAR(20),
    sla_due_date VARCHAR(20) NOT NULL
);

    
CREATE TABLE dim_account (
    account_key INTEGER NOT NULL,
    account_id VARCHAR(20) NOT NULL,
    customer_key INTEGER NOT NULL,
    product_key INTEGER NOT NULL,
    branch_key INTEGER NOT NULL,
    account_type VARCHAR(20) NOT NULL,
    sanction_amount DECIMAL(15,2),
    disbursed_amount DECIMAL(15,5) NOT NULL,
    interest_rate DECIMAL(5,2),
    tenure_months INTEGER NOT NULL,
    account_open_date VARCHAR(20) NOT NULL,
    account_status VARCHAR(20) NOT NULL,
    security_type VARCHAR(20) NOT NULL,
    consortium_flag VARCHAR(5) NOT NULL
);


    
 CREATE TABLE dim_branch (
    branch_key INTEGER NOT NULL,
    branch_code VARCHAR(20) NOT NULL,
    branch_name VARCHAR(100) NOT NULL,
    region VARCHAR(20) NOT NULL,
    zone VARCHAR(20) NOT NULL,
    state VARCHAR(50) NOT NULL,
    country VARCHAR(50) NOT NULL
);

    
CREATE TABLE dim_customer (
    customer_key INTEGER NOT NULL,
    customer_id VARCHAR(20) NOT NULL,
    customer_name VARCHAR(150) NOT NULL,
    customer_type VARCHAR(20) NOT NULL,
    pan_number VARCHAR(20),
    date_of_birth VARCHAR(20),
    incorporation_date VARCHAR(20),
    industry_sector VARCHAR(50),
    kyc_risk_category VARCHAR(20) NOT NULL,
    relationship_manager_id VARCHAR(20),
    onboarding_date VARCHAR(20) NOT NULL,
    credit_rating_internal VARCHAR(10),
    credit_rating_external VARCHAR(10),
    is_pep VARCHAR(5) NOT NULL
);


    
CREATE TABLE dim_product (
    product_key INTEGER NOT NULL,
    product_code VARCHAR(20) NOT NULL,
    product_name VARCHAR(100) NOT NULL,
    product_category VARCHAR(50) NOT NULL,
    lob VARCHAR(50) NOT NULL
);

    
CREATE TABLE fact_account_performance (
    fact_id INTEGER NOT NULL,
    account_key INTEGER NOT NULL,
    customer_key INTEGER NOT NULL,
    snapshot_date VARCHAR(20) NOT NULL,
    outstanding_balance DECIMAL(15,2),
    overdue_amount DECIMAL(15,2) NOT NULL,
    dpd_days INTEGER NOT NULL,
    dpd_bucket VARCHAR(20),
    sma_category VARCHAR(20) NOT NULL,
    emi_amount DECIMAL(15,2),
    emi_bounce_flag VARCHAR(5) NOT NULL,
    credit_utilization_ratio DECIMAL(10,4),
    min_due_paid_flag VARCHAR(5) NOT NULL,
    provision_amount DECIMAL(15,2) NOT NULL,
    restructured_flag VARCHAR(5) NOT NULL
);










    
CREATE TABLE fact_transaction (
    transaction_id INTEGER NOT NULL,
    account_key INTEGER NOT NULL,
    customer_key INTEGER NOT NULL,
    transaction_timestamp VARCHAR(30) NOT NULL,
    transaction_type VARCHAR(20) NOT NULL,
    channel VARCHAR(20) NOT NULL,
    amount DECIMAL(15,2),
    counterparty_account_id BIGINT NOT NULL,
    geo_location VARCHAR(50) NOT NULL,
    is_flagged_fraud VARCHAR(5) NOT NULL,
    fraud_score DECIMAL(10,4),
    status VARCHAR(20) NOT NULL
);











    
CREATE TABLE risk_score (
    score_id INTEGER NOT NULL,
    entity_type VARCHAR(20) NOT NULL,
    entity_key INTEGER NOT NULL,
    risk_domain VARCHAR(20) NOT NULL,
    raw_score DECIMAL(10,2) NOT NULL,
    normalized_score DECIMAL(10,2),
    risk_band VARCHAR(20) NOT NULL,
    score_date VARCHAR(20) NOT NULL
);

